input.command:
cd /workspace
echo "=== distinct explicit ids found in CAR ==="
time duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE TABLE lst AS SELECT * FROM read_csv_auto('lists/goias-sample.csv', header=true, all_varchar=true);
CREATE TABLE ids AS SELECT DISTINCT cod_imovel FROM lst WHERE cod_imovel IS NOT NULL AND cod_imovel<>'';
SELECT count(*) AS distinct_ids FROM ids;
CREATE TABLE car_ids AS
  SELECT DISTINCT cod_imovel FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
  WHERE cod_imovel IN (SELECT cod_imovel FROM ids);
SELECT count(*) AS found_in_car FROM car_ids;
SELECT count(*) AS missing FROM ids WHERE cod_imovel NOT IN (SELECT cod_imovel FROM car_ids);
"

cd /workspace
time duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE TABLE res AS SELECT cod_imovel FROM read_csv_auto('resolved_parcels.csv', header=true);
CREATE TABLE lst AS SELECT * FROM read_csv_auto('lists/goias-sample.csv', header=true, all_varchar=true);
CREATE TABLE listedids AS SELECT DISTINCT cod_imovel FROM lst WHERE cod_imovel IS NOT NULL AND cod_imovel<>'';
-- pull CAR rows for resolved parcels
CREATE TABLE carsub AS
 SELECT cod_imovel, municipio, num_area FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
 WHERE cod_imovel IN (SELECT cod_imovel FROM res);
-- CAR row count per id
CREATE TABLE rowcounts AS SELECT cod_imovel, count(*) AS nrows, min(num_area) AS num_area, any_value(municipio) AS municipio FROM carsub GROUP BY cod_imovel;
SELECT 'n_duplicate_ids' AS metric, count(*) AS v FROM rowcounts WHERE cod_imovel IN (SELECT cod_imovel FROM listedids) AND nrows>1
UNION ALL
SELECT 'n_parcels_under_1ha', count(*) FROM rowcounts WHERE num_area < 1
UNION ALL
SELECT 'total_resolved', count(*) FROM rowcounts;
"

cd /workspace
duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE TABLE res AS SELECT cod_imovel FROM read_csv_auto('resolved_parcels.csv', header=true);
CREATE TABLE carsub AS
 SELECT cod_imovel, any_value(municipio) municipio, min(num_area) num_area
 FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
 WHERE cod_imovel IN (SELECT cod_imovel FROM res) GROUP BY cod_imovel;
SELECT min(num_area) mn, max(num_area) mx, avg(num_area) av FROM carsub;
"
echo "=== q06 municipio breakdown ==="
duckdb -csv -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE TABLE res AS SELECT cod_imovel FROM read_csv_auto('resolved_parcels.csv', header=true);
COPY (
 SELECT municipio, count(DISTINCT cod_imovel) AS n_parcels FROM (
   SELECT cod_imovel, any_value(municipio) municipio
   FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet')
   WHERE cod_imovel IN (SELECT cod_imovel FROM res) GROUP BY cod_imovel)
 GROUP BY municipio ORDER BY n_parcels DESC, municipio
) TO 'answers/q06.csv' (HEADER, DELIMITER ',');
"
cat answers/q06.csv

cd /workspace
time duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE MACRO env() AS ST_MakeEnvelope(-51.51685499999999,-15.97435111,-51.20062249999998,-15.481647166112458);
COPY (
  SELECT Id, hansen_covered_area, hansen_loss_area, mode_year, firstyear, firstyearmajority,
         deforestarea0104, deforestarea0509, deforestarea1014, deforestarea1520, deforestarea2124,
         mbmode24, mbcov_area_2024, mbvalid_area_2024, geometry
  FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet')
  WHERE bbox.xmin <= -51.20062249999998 AND bbox.xmax >= -51.51685499999999
    AND bbox.ymin <= -15.481647166112458 AND bbox.ymax >= -15.97435111
    AND ST_Intersects(geometry, env())
) TO 'fields.parquet' (FORMAT parquet);
SELECT count(*) AS n_fields_in_envelope FROM read_parquet('fields.parquet');
"

cd /workspace
printf 'n_fields_in_envelope\n3291\n' > answers/q08.csv
time duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
-- projected parcels
CREATE TABLE p AS SELECT cod_imovel, municipio, ST_Transform(geometry,'EPSG:4326','EPSG:31982') AS gm FROM read_parquet('parcels.parquet');
-- union of all parcels (single geometry)
CREATE TABLE u AS SELECT ST_Union_Agg(gm) AS ug FROM p;
-- projected fields
CREATE TABLE f AS SELECT Id, ST_Transform(geometry,'EPSG:4326','EPSG:31982') AS gm FROM read_parquet('fields.parquet');
CREATE TABLE fa AS SELECT Id, gm, ST_Area(gm) AS field_area FROM f;
-- per (field,parcel) intersection where they intersect
CREATE TABLE pairs AS
  SELECT fa.Id, p.cod_imovel, p.municipio, fa.field_area,
         ST_Area(ST_Intersection(fa.gm, p.gm)) AS inter_area
  FROM fa JOIN p ON ST_Intersects(fa.gm, p.gm);
-- per field: best single parcel + union fraction
CREATE TABLE perfield AS
  SELECT fa.Id, fa.field_area,
    (SELECT max(inter_area) FROM pairs WHERE pairs.Id=fa.Id) AS best_inter,
    (SELECT arg_max(cod_imovel, inter_area) FROM pairs WHERE pairs.Id=fa.Id) AS best_parcel,
    (SELECT arg_max(municipio, inter_area) FROM pairs WHERE pairs.Id=fa.Id) AS best_muni,
    ST_Area(ST_Intersection(fa.gm, (SELECT ug FROM u))) AS union_inter
  FROM fa WHERE fa.Id IN (SELECT Id FROM pairs);
COPY (
  SELECT Id, field_area, best_parcel, best_muni,
         best_inter/field_area AS single_frac,
         union_inter/field_area AS union_frac
  FROM perfield
) TO 'field_matches.parquet' (FORMAT parquet);
SELECT count(*) AS fields_touching_parcels FROM read_parquet('field_matches.parquet');
"

cd /workspace
duckdb -box -c "
LOAD spatial;
CREATE TABLE mm AS SELECT Id, best_parcel, best_muni, field_area, single_frac, union_frac FROM read_parquet('field_matches.parquet') WHERE union_frac>=0.5;
CREATE TABLE fld AS SELECT * FROM read_parquet('fields.parquet');
COPY (
  SELECT mm.Id, mm.best_parcel, mm.best_muni, mm.field_area,
         f.deforestarea0104, f.deforestarea0509, f.deforestarea1014, f.deforestarea1520, f.deforestarea2124,
         f.mode_year, f.firstyear, f.firstyearmajority, f.hansen_loss_area,
         CAST(f.mbmode24 AS INTEGER) AS mbmode24, f.mbcov_area_2024, f.mbvalid_area_2024
  FROM mm JOIN fld f ON mm.Id=f.Id
) TO 'matched_fields.parquet' (FORMAT parquet);
SELECT CAST(mbmode24 AS INTEGER) AS mbmode24, count(*) n, round(sum(deforestarea2124)/10000,2) post2020_ha
FROM read_parquet('matched_fields.parquet') GROUP BY 1 ORDER BY n DESC;
"

cd /workspace
duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE TABLE fac AS SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');
SELECT tier, entity_kind, count(*) n, count(DISTINCT basis) nbasis, min(weight) wmin, max(weight) wmax FROM fac GROUP BY 1,2 ORDER BY 1,2;
"

cd /workspace
duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE TABLE fac AS SELECT entity_id, entity_kind, tier, weight, basis, geom_method, source FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');
SELECT tier, any_value(entity_id) eid, any_value(basis) basis, any_value(geom_method) gm, any_value(source) src FROM fac GROUP BY tier;
"
echo "=== distinct basis per tier ==="
duckdb -csv -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
SELECT tier, basis, count(*) n FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') GROUP BY 1,2 ORDER BY 1;"

cd /workspace
duckdb -box -c "
CREATE TABLE scope(mbmode24 INT, annex1_commodity VARCHAR, in_scope BOOLEAN);
INSERT INTO scope VALUES (15,'cattle',true),(21,'',false),(39,'soy',true),(41,'',false);
CREATE TABLE mf AS SELECT * FROM read_parquet('matched_fields.parquet');
-- flagged: parcels with post2020 loss on in-scope crops
CREATE TABLE flag AS
 SELECT best_parcel AS cod_imovel, any_value(best_muni) municipio,
   sum(deforestarea2124)/10000.0 total_loss,
   arg_max(mbmode24, deforestarea2124) dominant_mb
 FROM mf JOIN scope s ON mf.mbmode24=s.mbmode24
 WHERE s.in_scope
 GROUP BY best_parcel HAVING sum(deforestarea2124)>0;
SELECT count(*) AS n_flagged FROM flag;
SELECT dominant_mb, count(*) n FROM flag GROUP BY 1;
"

cd /workspace
duckdb -box -c "
CREATE TABLE scope(mbmode24 INT, annex1_commodity VARCHAR, in_scope BOOLEAN);
INSERT INTO scope VALUES (15,'cattle',true),(21,'',false),(39,'soy',true),(41,'',false);
CREATE TABLE mf AS SELECT * FROM read_parquet('matched_fields.parquet');
CREATE TABLE flag AS
 SELECT mf.best_parcel AS cod_imovel, any_value(mf.best_muni) municipio,
   sum(mf.deforestarea2124)/10000.0 total_loss,
   arg_max(mf.mbmode24, mf.deforestarea2124) dominant_mb
 FROM mf JOIN scope s ON mf.mbmode24=s.mbmode24
 WHERE s.in_scope
 GROUP BY mf.best_parcel HAVING sum(mf.deforestarea2124)>0;
COPY (SELECT f.cod_imovel, f.municipio, f.total_loss, f.dominant_mb, sc.annex1_commodity
      FROM flag f JOIN scope sc ON f.dominant_mb=sc.mbmode24) TO 'flagged.csv' (HEADER, DELIMITER ',');
SELECT count(*) AS n_flagged FROM flag;
SELECT dominant_mb, count(*) n FROM flag GROUP BY 1;
"
echo "=== flagged parcels ==="; cat flagged.csv

cd /workspace
time duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
CREATE TABLE flag AS SELECT * FROM read_csv_auto('flagged.csv', header=true);
-- parcel centroids in metric CRS
CREATE TABLE pc AS SELECT cod_imovel, ST_Transform(ST_Centroid(geometry),'EPSG:4326','EPSG:31982') AS gm FROM read_parquet('parcels.parquet') WHERE cod_imovel IN (SELECT cod_imovel FROM flag);
-- delivery facilities projected
CREATE TABLE fac AS SELECT entity_id, tier, ST_Transform(geometry,'EPSG:4326','EPSG:31982') AS gm
  FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet')
  WHERE tier IN ('slaughter_point','intake_point');
-- routed tier per flagged parcel
CREATE TABLE fr AS SELECT f.cod_imovel, CASE f.annex1_commodity WHEN 'cattle' THEN 'slaughter_point' WHEN 'soy' THEN 'intake_point' END rtier FROM flag f;
-- nearest facility of routed tier
COPY (
 SELECT fr.cod_imovel,
   (SELECT fac.entity_id FROM fac WHERE fac.tier=fr.rtier ORDER BY ST_Distance(fac.gm, pc.gm) LIMIT 1) AS entity_id,
   fr.rtier AS tier,
   (SELECT min(ST_Distance(fac.gm, pc.gm)) FROM fac WHERE fac.tier=fr.rtier)/1000.0 AS distance_km
 FROM fr JOIN pc ON fr.cod_imovel=pc.cod_imovel
 ORDER BY fr.cod_imovel
) TO 'answers/q26.csv' (HEADER, DELIMITER ',');
"
echo "--- q26 ---"; cat answers/q26.csv

cd /workspace
duckdb -box -c "
LOAD spatial; LOAD httpfs; SET geometry_always_xy=true;
-- membership_muni aggregated by municipio code
CREATE TABLE mem AS SELECT entity_id, sum(weight) AS members, count(*) ncoop
  FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet')
  WHERE tier='membership_muni' GROUP BY entity_id;
CREATE TABLE flag AS SELECT * FROM read_csv_auto('flagged.csv', header=true);
SELECT DISTINCT split_part(cod_imovel,'-',2) AS muni_code FROM flag;
SELECT * FROM mem WHERE entity_id IN ('5212204','5219258');
"
